import {api,escape} from './workspace-shared.js';
import {renderSummary} from './summary-format.mjs';
const recapLabel={waiting:'Waiting for End lesson and the Zoom transcript',ready:'AI class recap',needs_attention:'Transcript processing needs teacher attention'};
const quizLabel={waiting:'A quiz draft will be prepared after this lesson.',draft_ready:'Next-lesson quiz draft ready. Review and assign it from the next lesson’s quiz panel.',kept_existing:'Your existing next-lesson quiz or draft was kept.',no_next_lesson:'No next lesson is scheduled for a quiz draft.',no_upcoming_lesson:'The next lesson has already started or needs a valid future date.',needs_attention:'The quiz draft needs attention. Retry processing or use the quiz builder.'};
const weekdayNames=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
export async function openWeeklyZoom({classId,onChanged=()=>{},onError=()=>{}}){
 const path=`/api/zoom/classes/${classId}/weekly`,dialog=document.createElement('dialog');dialog.className='teacher-dialog zoom-settings';dialog.setAttribute('aria-label','Weekly Zoom links');dialog.innerHTML='<h2>Weekly Zoom links</h2><p role="status">Loading…</p>';document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove());let changed=false;
 try{let [state,connection]=await Promise.all([api(path),api('/api/zoom/connection')]);dialog.innerHTML=`<button type="button" class="teacher-close" aria-label="Close weekly Zoom links">×</button><h2>Weekly Zoom links</h2><p>Save the regular meeting for each teaching day. Lessons use the link for their scheduled weekday; a meeting set on an individual lesson takes priority.</p><ul data-weekly-saved></ul><form><label>Teaching day<select name="weekday">${weekdayNames.map((name,i)=>`<option value="${i}">${name}</option>`).join('')}</select></label><label>Participant meeting link<input name="joinURL" type="url" placeholder="https://zoom.us/j/…"></label><label>Meeting ID<input name="meetingId" inputmode="numeric" maxlength="20"></label><label>Passcode (optional)<input name="passcode" maxlength="64"></label><fieldset><legend>After future lessons</legend><p>${connection.connected?'Connected to '+escape(connection.displayName):'Connect the Zoom account that hosts this meeting to enable transcripts.'}</p>${connection.configured?'<button type="button" class="text-button" data-weekly-connect>'+(connection.connected?'Reconnect Zoom':'Connect Zoom')+'</button>':''}<label><input type="checkbox" name="autoRecap"> Automatically post a class recap</label><label><input type="checkbox" name="autoQuiz"> Also prepare a private quiz draft for the next lesson</label><p class="planner-hint">After End lesson, the available Zoom transcript is sent to OpenAI. Enable retained transcripts or cloud recording transcription in Zoom. Raw transcripts are not saved in Ink Wire. Review quiz drafts before assigning; existing quizzes are kept.</p></fieldset><p role="status" aria-live="polite"></p><button type="submit" class="teacher-button">Save weekday meeting</button><button type="button" class="text-button" data-remove-weekly>Remove weekday meeting</button></form><p class="planner-hint">For future lessons, match your regular meeting to the timetable. Keep lesson times up to date; unclear matches are left for teacher review.</p>`;
  const form=dialog.querySelector('form'),day=form.elements.weekday,status=message=>dialog.querySelector('[role=status]').textContent=message,remove=dialog.querySelector('[data-remove-weekly]');day.value=String(state.meetings[0]?.weekday??5);
  function render(){const saved=state.meetings.find(m=>m.weekday===Number(day.value));for(const name of ['joinURL','meetingId','passcode'])form.elements[name].value=saved?.[name]||'';for(const name of ['autoRecap','autoQuiz'])form.elements[name].checked=Boolean(saved?.[name]);form.elements.autoQuiz.disabled=!form.elements.autoRecap.checked;remove.disabled=!saved;dialog.querySelector('[data-weekly-saved]').innerHTML=state.meetings.sort((a,b)=>a.weekday-b.weekday).map(m=>`<li>${weekdayNames[m.weekday]} · Meeting ID ${escape(m.meetingId)}</li>`).join('');}render();form.elements.autoRecap.onchange=()=>{form.elements.autoQuiz.disabled=!form.elements.autoRecap.checked;if(!form.elements.autoRecap.checked)form.elements.autoQuiz.checked=false;};const connect=dialog.querySelector('[data-weekly-connect]');if(connect)connect.onclick=async()=>{connect.disabled=true;try{const result=await api('/api/zoom/connection',{action:'connect',expectedUserId:connection.userId});location.assign(result.url);}catch(error){status(error.message);connect.disabled=false;}};day.onchange=()=>{render();status('');};
  dialog.querySelector('.teacher-close').onclick=async()=>{dialog.close();if(changed)await onChanged();};
  dialog.addEventListener('cancel',()=>{if(changed)onChanged();});
  async function submit(action){const current=state.meetings.find(m=>m.weekday===Number(day.value));const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{state=await api(path,{action,...Object.fromEntries(new FormData(form)),weekday:Number(day.value),autoRecap:form.elements.autoRecap.checked,autoQuiz:form.elements.autoRecap.checked&&form.elements.autoQuiz.checked,expectedUserId:state.userId,revision:current?.revision||0});changed=true;render();status(weekdayNames[Number(day.value)]+' meeting '+(action==='save'?'saved.':'removed.'));}catch(error){status(error.message);}finally{buttons.forEach(b=>b.disabled=false);remove.disabled=!state.meetings.some(m=>m.weekday===Number(day.value));}}
  form.onsubmit=event=>{event.preventDefault();submit('save');};remove.onclick=()=>{if(confirm('Remove the regular '+weekdayNames[Number(day.value)]+' Zoom link? Individual lesson meetings stay saved.'))submit('remove');};
 }catch(error){dialog.close();onError(error.message);}
}
export function zoomMeetingHTML(meeting){
 if(!meeting)return '<p class="planner-hint">Your teacher has not added a Zoom meeting yet.</p>';
 if(!meeting.meetingId)return '<p class="planner-hint">Zoom meeting setup needs checking. The teacher can review it in Zoom.</p>';
 return `<div class="timeline-zoom-join"><a class="teacher-button" href="${escape(meeting.joinURL)}" target="_blank" rel="noopener noreferrer">Join Zoom ↗</a><span>Meeting ID: <strong>${escape(meeting.meetingId)}</strong>${meeting.passcode?' · Passcode: <strong>'+escape(meeting.passcode)+'</strong>':''}</span></div>${meeting.inherited?`<p class="planner-hint">${weekdayNames[meeting.weekday]} class meeting</p>`:''}${meeting.recordingURL?`<p><a href="${escape(meeting.recordingURL)}" target="_blank" rel="noopener noreferrer">Watch class recording ↗</a></p>`:''}${meeting.autoRecap?`<p class="planner-hint">${escape(recapLabel[meeting.recapStatus]||'Preparing class recap')}</p>`:''}${meeting.recapSummary?'<details class="timeline-details"><summary>AI class recap</summary><div data-zoom-recap></div></details>':''}`;
}
export function mountZoomMeeting({root,classId,lesson,teacher=false,onChanged=()=>{},onError=()=>{}}){
 root.className='timeline-zoom';const path=`/api/zoom/classes/${classId}/lessons/${lesson.id}`;
 function render(meeting){root.innerHTML='<h4>Zoom meeting</h4>'+zoomMeetingHTML(meeting);if(meeting?.recapSummary)renderSummary(root.querySelector('[data-zoom-recap]'),meeting.recapSummary);if(teacher){if(meeting?.autoQuiz){const note=document.createElement('p');note.className='planner-hint';note.textContent=quizLabel[meeting.quizStatus]||quizLabel.waiting;root.append(note);}const button=document.createElement('button');button.type='button';button.className='text-button';button.textContent=meeting?'Meeting settings':'Add Zoom meeting';button.onclick=()=>openSettings();root.append(button);}}
 render(lesson.zoom);
 async function openSettings(){
  const dialog=document.createElement('dialog');dialog.className='teacher-dialog zoom-settings';dialog.setAttribute('aria-label','Zoom meeting settings');dialog.innerHTML='<h2>Zoom meeting</h2><p role="status">Loading meeting settings…</p>';document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove());
  try{
   const [state,connection]=await Promise.all([api(path),api('/api/zoom/connection')]),meeting=state.meeting?.inherited?null:state.meeting;
   dialog.innerHTML=`<button type="button" class="teacher-close" aria-label="Close Zoom settings">×</button><h2>Zoom meeting</h2><p role="status"></p><p>${connection.connected?'Connected to '+escape(connection.displayName):'Connect your Zoom account to create meetings and use automatic recaps.'}</p>${connection.configured?`<button type="button" class="teacher-button secondary" data-connect-zoom>${connection.connected?'Reconnect Zoom':'Connect Zoom'}</button>${connection.connected?'<button type="button" class="text-button" data-disconnect-zoom>Disconnect Zoom</button>':''}`:'<p class="planner-hint">The Zoom account connection is awaiting site configuration. You can still attach an existing meeting below.</p>'}${!meeting?`<form data-zoom-form><label>Participant meeting link <input name="joinURL" type="url" placeholder="https://zoom.us/j/…"></label><label>Meeting ID <input name="meetingId" inputmode="numeric" maxlength="20"></label><label>Passcode (optional) <input name="passcode" maxlength="64"></label><label>Recording sharing link (optional) <input name="recordingURL" type="url"></label><button class="teacher-button" type="submit">Save meeting details</button></form>${connection.connected?'<hr><label><input type="checkbox" data-auto-recap> Automatically post a class recap from the Zoom transcript</label><label><input type="checkbox" data-auto-quiz> Also prepare a private quiz draft for the next lesson</label><p class="planner-hint">This sends the available transcript to OpenAI after End lesson. Enable retained transcripts or cloud recording transcription in Zoom. Review quiz drafts before assigning; existing quizzes are kept.</p><button type="button" class="teacher-button" data-create-zoom>Create a meeting for this lesson</button>':''}`:meeting.managed?`<p>Ink Wire manages this lesson’s meeting. Meeting changes made directly in Zoom do not yet update the course schedule.</p>${(meeting.recapStatus==='needs_attention'||meeting.quizStatus==='needs_attention')?'<button type="button" class="teacher-button secondary" data-retry-recap>Retry transcript processing</button>':''}`:`<form data-zoom-form><label>Participant meeting link <input name="joinURL" type="url" value="${escape(meeting.joinURL)}"></label><label>Meeting ID <input name="meetingId" inputmode="numeric" value="${escape(meeting.meetingId)}"></label><label>Passcode (optional) <input name="passcode" maxlength="64" value="${escape(meeting.passcode)}"></label><label>Recording sharing link (optional) <input name="recordingURL" type="url" value="${escape(meeting.recordingURL)}"></label><button class="teacher-button" type="submit">Save meeting details</button></form>`}${meeting?'<p class="planner-hint">Removing the lesson link does not delete the meeting from Zoom.</p><button type="button" class="text-button" data-remove-zoom>Remove meeting from lesson</button>':''}`;
   const status=message=>dialog.querySelector('[role=status]').textContent=message;dialog.querySelector('.teacher-close').onclick=()=>dialog.close();
   async function submit(body){const buttons=[...dialog.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await api(path,{...body,revision:meeting?.revision||0,expectedUserId:state.userId});dialog.close();await onChanged();}catch(error){status(error.message);buttons.forEach(b=>b.disabled=false);}}
   dialog.querySelector('[data-zoom-form]')?.addEventListener('submit',event=>{event.preventDefault();submit({action:'save',...Object.fromEntries(new FormData(event.target))});});
   if(meeting?.managed){const section=document.createElement('section');section.innerHTML=`<label><input type="checkbox" data-recap-enabled ${meeting.autoRecap?'checked':''}> Automatically post a recap from the Zoom transcript</label><label><input type="checkbox" data-quiz-enabled ${meeting.autoQuiz?'checked':''}> Also prepare a private quiz draft for the next lesson</label><p class="planner-hint">When enabled, Zoom transcripts are sent to OpenAI after End lesson. Existing published recaps stay saved. Review quiz drafts before assigning; existing quizzes are kept.</p><button type="button" class="teacher-button secondary" data-save-recap-setting>Save recap setting</button>${meeting.recapStatus==='ready'?'<details><summary>Correct the AI class recap</summary><form data-recap-form><label>Shared class recap<textarea name="summary" rows="10" maxlength="14000"></textarea></label><button class="teacher-button" type="submit">Save corrected recap</button></form></details>':''}`;dialog.append(section);section.querySelector('[data-save-recap-setting]').onclick=()=>submit({action:'recap-setting',autoRecap:section.querySelector('[data-recap-enabled]').checked,autoQuiz:section.querySelector('[data-recap-enabled]').checked&&section.querySelector('[data-quiz-enabled]').checked});const form=section.querySelector('[data-recap-form]');if(form){form.elements.summary.value=meeting.recapSummary;form.onsubmit=event=>{event.preventDefault();submit({action:'correct-recap',summary:form.elements.summary.value});};}}
   const connect=dialog.querySelector('[data-connect-zoom]');if(connect)connect.onclick=async()=>{connect.disabled=true;try{const result=await api('/api/zoom/connection',{action:'connect',expectedUserId:connection.userId});location.assign(result.url);}catch(error){status(error.message);connect.disabled=false;}};
   const disconnect=dialog.querySelector('[data-disconnect-zoom]');if(disconnect)disconnect.onclick=async()=>{if(!confirm('Disconnect Zoom? Existing meeting links stay, but automatic controls and recaps stop until you reconnect.'))return;disconnect.disabled=true;try{await api('/api/zoom/connection',{action:'disconnect',expectedUserId:connection.userId});dialog.close();await onChanged();}catch(error){status(error.message);disconnect.disabled=false;}};
   const create=dialog.querySelector('[data-create-zoom]');if(create)create.onclick=()=>submit({action:'create',autoRecap:dialog.querySelector('[data-auto-recap]').checked,autoQuiz:dialog.querySelector('[data-auto-recap]').checked&&dialog.querySelector('[data-auto-quiz]').checked});
   const remove=dialog.querySelector('[data-remove-zoom]');if(remove)remove.onclick=()=>{if(confirm('Remove this lesson’s Zoom link? The meeting itself stays in Zoom. Check Zoom for an existing meeting before creating another.'))submit({action:'remove'});};
   const retry=dialog.querySelector('[data-retry-recap]');if(retry)retry.onclick=()=>submit({action:'retry-recap'});
  }catch(error){dialog.close();onError(error.message);}
 }
 if(!teacher){let prior=JSON.stringify(lesson.zoom);async function poll(){if(!root.isConnected)return;if(!root.closest('[hidden]')&&document.visibilityState==='visible'){try{const result=await api(path),next=JSON.stringify(result.meeting);if(next!==prior){prior=next;render(result.meeting);}}catch{/* Keep the last known join details during a temporary outage. */}}setTimeout(poll,30000);}setTimeout(poll,30000);}
}
